// ── Data loading ─────────────────────────────────────────────────────────
// Real static site (unlike the sandboxed artifact) can fetch its own data,
// so this is the single source of truth generated by build_data.py.
let C, CSV, SRC_JP, SRC_DEVICES, HIGHLIGHTS, REAL_DATA, SRC_FURIGANA,
    SRC_DEVICE_LABELS, HIGHLIGHT_LABELS, HIGHLIGHT_DEVICE_KEYS;

// cache:'no-cache' — poems.json has no version query param the way
// app.js/style.css do, so a browser that already had it cached could keep
// serving stale data (including now-fixed content bugs) indefinitely after
// a rebuild. This forces a revalidation with the server on every load
// (a cheap 304 when nothing changed) instead of trusting a blind cache hit.
fetch('./data/poems.json', {cache:'no-cache'})
  .then(r => r.json())
  .then(data => {
    ({C, CSV, SRC_JP, SRC_DEVICES, HIGHLIGHTS, REAL_DATA, SRC_FURIGANA,
      SRC_DEVICE_LABELS = {}, HIGHLIGHT_LABELS = {}, HIGHLIGHT_DEVICE_KEYS = {}} = data);
    init();
  })
  .catch(err => {
    document.getElementById('grid').innerHTML =
      '<p style="padding:2rem;color:#b23a12;">Failed to load data/poems.json — ' + err + '</p>';
  });

function init(){




// ── Bar colors — GENERATED from build_data.py palette; edit colors there ────

const DCOLORS=[C.kakekotoba,C.makurakotoba,C.kigo];

const TRANS_LBLS=['D','M','N','P'];
const TRANS_NAMES={D:'F.V. Dickins 1866',M:'MacCauley 1899',N:'Noguchi 1907',P:'Porter 1909'};

// ── Placeholder for poems with no AI annotation yet ────────────────────────
// Deliberately carries NO fabricated structure: bar lengths come from the
// real translation line counts already in CSV, and every segment is the flat
// neutral color — never kami/shimo/imagined/device colors, which would imply
// analysis that hasn't happened.
function mkPlaceholder(n){
  const row=CSV[String(n)]||{};
  const bars=['O',...TRANS_LBLS].map(lbl=>{
    const isO=lbl==='O';
    const nLines=isO?5:((row[lbl]&&row[lbl].length)||1);
    const segs=Array.from({length:nLines},()=>({type:'unanalyzed'}));
    return{lbl,segs,nLines};
  });
  return{n,bars,real:false};
}

// ── Real data for analyzed poems ───────────────────────────────────────────
const BAR_ORDER=['O','D','M','N','P'];
const POEMS=Array.from({length:100},(_,i)=>{
  const n=i+1;
  const poem=REAL_DATA[n]||mkPlaceholder(n);
  poem.bars.sort((a,b)=>BAR_ORDER.indexOf(a.lbl)-BAR_ORDER.indexOf(b.lbl));
  return poem;
});

// ── SVG bar rendering ──────────────────────────────────────────────────────
// Spec: all bars 8pt, 15pt gap after O, 9pt between translations
// 8+15+4*8+3*9 = 82 — fills cell exactly, square viewBox
const DIM=82;
const SVG_W_BARS=82;
const BAR_X=[0, 23, 40, 57, 74];   // O=0, D=23, N=40, M=57, P=74
const BAR_W=[8, 8, 8, 8, 8];

function f(v){return Math.round(v*10)/10;}

// For analyzed poems: compute each device's fractional position in the JP poem.
// Returns { hexColor: [frac, frac, ...] } sorted by appearance order.
// Returns each device's actual character SPAN as a fraction of the poem's
// total length — {start, end}, not a centered point — so the rendered band
// covers exactly the word's own length with no artificial gap or padding
// around it. A word at position 0 starts its band at literal position 0.
function jpDeviceFracs(n) {
  const jpRaw = SRC_JP[String(n)] || '';
  if (!jpRaw) return {};
  const jp = jpRaw.replace(/\n/g,'');
  const total = jp.length;
  const devs = SRC_DEVICES[String(n)] || {};
  const byColor = {};
  // Sort entries by appearance position in jp text for stable ordering
  Object.entries(devs)
    .filter(([w]) => w !== 'none' && jp.includes(w))
    .sort(([a],[b]) => jp.indexOf(a) - jp.indexOf(b))
    .forEach(([word, color]) => {
      const pos = jp.indexOf(word);
      const span = {start: pos/total, end: (pos+word.length)/total, word};
      (byColor[color] = byColor[color]||[]).push(span);
    });
  return byColor;
}

function gridDeviceColor(dc){
  return dc;
}

// "Structure" mode shows ONLY kami-no-ku / shimo-no-ku / imagined-line — the
// bipartite skeleton. "Device" mode adds kakekotoba, makurakotoba, and kigo
// highlights on top. Nothing about the underlying data changes between the
// two — this is purely which layers glyph()/openModal() choose to draw.
let viewMode = 'device';

function glyph(poem, withTips){
  const maxLines=Math.max(...poem.bars.map(b=>b.nLines));
  // Precompute JP device positions for analyzed poems
  const jpFracs = (viewMode==='device' && poem.real) ? jpDeviceFracs(poem.n) : {};
  // Per-color usage counter resets for each bar
  const parts=[];
  poem.bars.forEach((bar,bi)=>{
    const x=BAR_X[bi], bw=BAR_W[bi];
    const bh=f((bar.nLines/maxLines)*DIM);
    const sh=bh/bar.nLines;
    const rx=bw/2;
    const cid=`c${poem.n}_${bi}`;
    parts.push(`<defs><clipPath id="${cid}"><rect x="${x}" y="0" width="${bw}" height="${bh}" rx="${rx}"/></clipPath></defs>`);
    parts.push(`<g clip-path="url(#${cid})">`);
    let y=0;
    bar.segs.forEach(seg=>{
      const fc=seg.type==='kami'?C.kami:seg.type==='shimo'?C.shimo:seg.type==='imagined'?C.imagined:C.unanalyzed;
      parts.push(`<rect x="${x}" y="${f(y)}" width="${bw}" height="${f(sh+.5)}" fill="${fc}"/>`);
      y+=sh;
    });
    // Device bands only draw in "device" mode — "structure" mode stops here,
    // leaving only the kami/shimo/imagined base colors from above.
    // For O bar of analyzed poems: draw device bands spanning EXACTLY each
    // word's own character range — no centering, no padding, no gap before
    // a word that starts at position 0. For translation bars: a device
    // covers the FULL segment (the whole line), since that's the finest
    // resolution the data actually has — a partial-height sliver inside the
    // segment would imply a precision about sub-line word position that
    // doesn't exist for translation lines.
    if(viewMode==='device' && bi===0 && poem.real && Object.keys(jpFracs).length>0){
      // withTips (the zoom card's "bars" stage only — not the resting
      // grid's 100 cells, which would pay this cost for no benefit) makes
      // each device band hoverable, showing which word lives at that
      // position — "can see the word at that position" instead of just a
      // colored band with no way to tell what it represents.
      const devLabels = withTips ? (SRC_DEVICE_LABELS[String(poem.n)]||{}) : null;
      Object.entries(jpFracs).forEach(([dc,spans])=>{
        spans.forEach(({start,end,word})=>{
          const label = devLabels && word ? devLabels[word] : null;
          const tipAttr = label ? ` data-tip="${escHtml(label)}"` : '';
          parts.push(`<rect x="${x}" y="${f(start*bh)}" width="${bw}" height="${f((end-start)*bh)}" fill="${gridDeviceColor(dc)}"${tipAttr}/>`);
        });
      });
    } else if(viewMode==='device'){
      // Each device band sits at that word's own position WITHIN this
      // line's text (fraction of the line's length) — not an even split by
      // device count. Each band is placed at its word's position in the line.
      let sy=0;
      bar.segs.forEach(seg=>{
        const devs = seg.devs || (seg.dev!=null ? [{color:seg.dev,start:0,end:1}] : []);
        devs.forEach(({color,start,end})=>{
          const dc=typeof color==='string'&&color[0]==='#'?color:DCOLORS[color];
          const y0=sy+start*sh, y1=sy+end*sh;
          parts.push(`<rect x="${x}" y="${f(y0)}" width="${bw}" height="${f(Math.max(y1-y0,1.2))}" fill="${gridDeviceColor(dc)}"/>`);
        });
        sy+=sh;
      });
    }
    parts.push('</g>');
  });
  // At zoom level 1 (withTips) show translator initial above each bar.
  const HDR = withTips ? 10 : 0;
  if(withTips){
    poem.bars.forEach((bar,bi)=>{
      const cx=f(BAR_X[bi]+BAR_W[bi]/2);
      parts.push(`<text x="${cx}" y="-2" text-anchor="middle" font-family="Inter,system-ui,sans-serif" font-size="6.5" font-weight="600" fill="#555">${escHtml(bar.lbl)}</text>`);
    });
  }
  // xMidYMid (not xMinYMin) — the zoom card's "bars" body is header-height
  // minus the cell's full height, so it's rarely exactly square anymore.
  // Anchoring at the min corner left the bars visibly clustered toward
  // one side with dead space on the other; centering the viewBox in
  // whichever dimension is smaller keeps them centered regardless.
  return `<svg width="100%" height="100%" viewBox="0 ${withTips?`-${HDR}`:0} ${SVG_W_BARS} ${DIM+HDR}" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">${parts.join('')}</svg>`;
}

// Renders ONE bar (not all five) at full cell height — used by the By-Author
// layout, where each mini-cell is a single translator's take on one poem
// rather than the by-poem view's five-bars-side-by-side comparison. Same
// color/device logic as glyph(), just without the multi-bar clip positions.
const AUTHOR_BAR_W=24;
function glyphOneBar(poem, bi){
  const bar=poem.bars[bi];
  const jpFracs=(viewMode==='device' && poem.real && bi===0) ? jpDeviceFracs(poem.n) : {};
  const W=AUTHOR_BAR_W, bh=DIM, sh=bh/bar.nLines, rx=2;
  const cid=`ab${poem.n}_${bi}`;
  const parts=[];
  parts.push(`<defs><clipPath id="${cid}"><rect x="0" y="0" width="${W}" height="${bh}" rx="${rx}"/></clipPath></defs>`);
  parts.push(`<g clip-path="url(#${cid})">`);
  let y=0;
  bar.segs.forEach(seg=>{
    const fc=seg.type==='kami'?C.kami:seg.type==='shimo'?C.shimo:seg.type==='imagined'?C.imagined:C.unanalyzed;
    parts.push(`<rect x="0" y="${f(y)}" width="${W}" height="${f(sh+.5)}" fill="${fc}"/>`);
    y+=sh;
  });
  if(viewMode==='device' && bi===0 && poem.real && Object.keys(jpFracs).length>0){
    Object.entries(jpFracs).forEach(([dc,spans])=>{
      spans.forEach(({start,end})=>{
        parts.push(`<rect x="0" y="${f(start*bh)}" width="${W}" height="${f((end-start)*bh)}" fill="${gridDeviceColor(dc)}"/>`);
      });
    });
  } else if(viewMode==='device'){
    let sy=0;
    bar.segs.forEach(seg=>{
      const devs=seg.devs || (seg.dev!=null ? [{color:seg.dev,start:0,end:1}] : []);
      devs.forEach(({color,start,end})=>{
        const dc=typeof color==='string'&&color[0]==='#'?color:DCOLORS[color];
        const y0=sy+start*sh, y1=sy+end*sh;
        parts.push(`<rect x="0" y="${f(y0)}" width="${W}" height="${f(Math.max(y1-y0,1.2))}" fill="${gridDeviceColor(dc)}"/>`);
      });
      sy+=sh;
    });
  }
  parts.push('</g>');
  return `<svg width="100%" height="100%" viewBox="0 0 ${W} ${DIM}" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">${parts.join('')}</svg>`;
}

// ── By-Author layout: 5 panels, each a compact 10×10 grid of one
// translator's 100 poems, for corpus-wide comparison instead of poem-by-poem.
const AUTHOR_SLOTS=[
  {key:'O', label:'原文 Source'},
  {key:'D', label:'F.V. Dickins 1866'},
  {key:'M', label:'MacCauley 1917'},
  {key:'N', label:'Noguchi 1907'},
  {key:'P', label:'Porter 1909'},
];
let authorGridsBuilt=false;
function buildAuthorGrids(){
  const container=document.getElementById('authorGrids');
  container.innerHTML='';
  const row=document.createElement('div');
  row.className='author-panels-row';
  AUTHOR_SLOTS.forEach(slot=>{
    const panel=document.createElement('div');
    panel.className='author-panel';
    const label=document.createElement('div');
    label.className='author-panel-label';
    label.textContent=slot.label;
    panel.appendChild(label);
    const mg=document.createElement('div');
    mg.className='author-mini-grid';
    POEMS.forEach(poem=>{
      const bi=poem.bars.findIndex(b=>b.lbl===slot.key);
      const cell=document.createElement('div');
      cell.className='author-cell';
      cell.tabIndex=0;
      cell.dataset.n=poem.n;
      cell.dataset.slot=slot.key;
      cell.title=`Poem ${poem.n}`;
      cell.setAttribute('aria-label',`Poem ${poem.n}, ${slot.label}`);
      if(bi!==-1) cell.innerHTML=glyphOneBar(poem, bi);
      cell.addEventListener('click', ()=>openModal(poem.n));
      cell.addEventListener('keydown', e=>{if(e.key==='Enter'||e.key===' ')openModal(poem.n);});
      cell.addEventListener('mouseenter', ()=>updateAuthorHighlight(poem.n));
      cell.addEventListener('mouseleave', ()=>updateAuthorHighlight(0));
      mg.appendChild(cell);
    });
    panel.appendChild(mg);
    row.appendChild(panel);
  });
  container.appendChild(row);
  const leg=document.createElement('div');
  leg.className='author-legend'+(viewMode==='structure'?' structure-only':'');
  leg.id='authorLegend';
  leg.innerHTML=`<div class="author-poem-info" id="authorPoemInfo"></div>
    <strong>Legend</strong>
    <div class="legend-row"><div class="legend-swatch" style="background:#2E9E6B"></div>Kaminoku</div>
    <div class="legend-row"><div class="legend-swatch" style="background:#E5503A"></div>Shimonoku</div>
    <div class="legend-row"><div class="legend-swatch" style="background:#6F63C9"></div>Imagined ku</div>
    <div class="legend-row legend-device"><div class="legend-swatch" style="background:#F28FC0"></div>Kakekotoba</div>
    <div class="legend-row legend-device"><div class="legend-swatch" style="background:#7EBBEE"></div>Makurakotoba</div>
    <div class="legend-row legend-device"><div class="legend-swatch" style="background:#B4DE65"></div>Kigo</div>`;
  container.appendChild(leg);
  authorGridsBuilt=true;
}
function updateAuthorHighlight(n){
  const container=document.getElementById('authorGrids');
  document.querySelectorAll('.author-cell').forEach(c=>c.classList.toggle('author-hl',+c.dataset.n===n));
  if(n) container.setAttribute('data-hl',n);
  else container.removeAttribute('data-hl');
  const info=document.getElementById('authorPoemInfo');
  if(!info) return;
  if(n){
    const poet=(CSV[String(n)]||{}).poet||'';
    info.textContent=`Poem ${n}${poet?' — '+poet:''}`;
  } else {
    info.textContent='';
  }
}
function refreshAuthorGrids(){
  if(!authorGridsBuilt) return;
  document.querySelectorAll('.author-cell').forEach(cell=>{
    const poem=POEMS[+cell.dataset.n-1];
    const bi=poem.bars.findIndex(b=>b.lbl===cell.dataset.slot);
    cell.innerHTML = bi!==-1 ? glyphOneBar(poem, bi) : '';
  });
}

let layoutMode='poem'; // 'poem' | 'author'
function setLayoutMode(mode){
  if(mode===layoutMode) return;
  layoutMode=mode;
  document.getElementById('vtByPoem').classList.toggle('active', mode==='poem');
  document.getElementById('vtByAuthor').classList.toggle('active', mode==='author');
  document.querySelector('.grid-nav').style.display = mode==='poem' ? 'grid' : 'none';
  document.getElementById('authorGrids').style.display = mode==='author' ? 'flex' : 'none';
  if(mode==='author' && !authorGridsBuilt) buildAuthorGrids();
}

// ── Build grid ────────────────────────────────────────────────────────────
// Explicit row/col placement (reading order), skipping the legend's
// reserved 2×2 block at rows 7–8 / cols 12–13 — same footprint the old
// auto-flow dense layout produced, but deterministic so the row-zoom
// interaction can look up "which cells are in row N" directly.
// Column-major, right-to-left (mirroring Japanese reading order): poem 1 at
// col13/row1, poem 2 at col13/row2, ..., poem 8 at col13/row8, poem 9 at
// col12/row1, and so on — reads top-to-bottom within a column, columns
// advance right→left. Skips the legend's reserved 2×2 block at the
// bottom-LEFT corner (rows 7–8, cols 1–2), so those two columns only get
// 6 poems each.
function nextGridPos(state, gridCols, gridRows){
  while(state.row>=gridRows-1 && state.col<=2){
    state.row++;
    if(state.row>gridRows){state.row=1;state.col--;}
  }
  const pos={row:state.row,col:state.col};
  state.row++;
  if(state.row>gridRows){state.row=1;state.col--;}
  return pos;
}

function computeGridDims(){
  const mobile = window.matchMedia('(max-width:640px)').matches;
  return mobile ? {cols:8, rows:13} : {cols:13, rows:8};
}

let GRID_COLS=13, GRID_ROWS=8;

function buildGrid(){
  const grid=document.getElementById('grid');
  grid.querySelectorAll('.pc').forEach(el=>el.remove());
  const dims=computeGridDims();
  GRID_COLS=dims.cols; GRID_ROWS=dims.rows;
  // .legend is a sibling of #grid (see index.html), pinned via CSS
  // position:absolute to the bottom-LEFT corner in both orientations —
  // right-to-left fill means the "end" of the text lands at the left.
  // nextGridPos reserves that same 2×2 corner.
  const state={row:1,col:GRID_COLS};
  POEMS.forEach(poem=>{
    const {row,col}=nextGridPos(state, GRID_COLS, GRID_ROWS);
    const cell=document.createElement('div');
    cell.className='pc'+(poem.real?' analyzed':'');
    cell.tabIndex=0;
    cell.dataset.n=poem.n;
    cell.dataset.row=row;
    cell.dataset.col=col;
    cell.style.gridRow=row;
    cell.style.gridColumn=col;
    cell.setAttribute('aria-label',`Poem ${poem.n}`);
    cell.innerHTML=`<div class="glyph-wrap">${glyph(poem)}</div>`;
    cell.addEventListener('click',e=>onCellClick(e,cell,poem));
    cell.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')openModal(poem.n);});
    grid.appendChild(cell);
  });
  buildNavRails();
}

// ── Row/column steppers ───────────────────────────────────────────────────
// Discrete alternative to the hover-magnifier below: clicking a rail button
// jumps the selection one column or row at a time, snapping onto whichever
// cell is currently selected on the OTHER axis (selRow/selCol), rather than
// always resetting to row/col 1. Drives the same applyZoom() the mouse uses,
// so both paths always agree on "what's currently selected."
let selRow=1, selCol=1;
let stepperLock=false;

function buildNavRails(){
  const colRail=document.getElementById('colRail');
  const rowRailR=document.getElementById('rowRailRight');
  if(colRail) colRail.innerHTML='';
  if(rowRailR) rowRailR.innerHTML='';
  for(let c=1;c<=GRID_COLS;c++){
    if(!colRail) continue;
    const btn=document.createElement('button');
    btn.className='nav-btn'; btn.type='button'; btn.dataset.col=c; btn.textContent='·';
    btn.addEventListener('click',()=>selectCell(selRow,c));
    colRail.appendChild(btn);
  }
  for(let r=1;r<=GRID_ROWS;r++){
    if(!rowRailR) continue;
    const btn=document.createElement('button');
    btn.className='nav-btn'; btn.type='button'; btn.dataset.row=r; btn.textContent='·';
    btn.addEventListener('click',()=>selectCell(r,selCol));
    rowRailR.appendChild(btn);
  }
  updateRailActive();
}

function updateRailPoem(num){
  document.querySelectorAll('.col-rail .nav-btn.active,.row-rail .nav-btn.active').forEach(b=>{b.textContent=num;});
}

function selectCell(row,col){
  const cell=document.querySelector(`#grid .pc[data-row="${row}"][data-col="${col}"]`);
  if(!cell) return;
  stepperLock=true;
  applyZoom(cell);
}

function updateRailActive(){
  document.querySelectorAll('.col-rail .nav-btn').forEach(b=>b.classList.toggle('active', +b.dataset.col===selCol));
  document.querySelectorAll('.row-rail .nav-btn').forEach(b=>b.classList.toggle('active', +b.dataset.row===selRow));
}

let _lastGridWasMobile=window.matchMedia('(max-width:640px)').matches;
window.addEventListener('resize', ()=>{
  const nowMobile=window.matchMedia('(max-width:640px)').matches;
  if(nowMobile!==_lastGridWasMobile){
    _lastGridWasMobile=nowMobile;
    buildGrid();
  }
});

function updateHdHeight(){
  const hd = document.querySelector('.hd');
  if(hd) document.documentElement.style.setProperty('--hd-h', hd.offsetHeight+'px');
}
updateHdHeight();
window.addEventListener('resize', updateHdHeight);
if(window.ResizeObserver){
  new ResizeObserver(updateHdHeight).observe(document.querySelector('.hd'));
}

// ── Text highlighting ─────────────────────────────────────────────────────
// Highlight backgrounds match the legend swatch exactly (full color, not a
// lightened tint). Text stays black everywhere — never white — so every
// device color in the palette (build_data.py) is deliberately kept light
// enough for black text to read cleanly on it.
function highlightLine(text, wordMap, labelMap, deviceKeyMap){
  if(!wordMap||!Object.keys(wordMap).length) return escHtml(text);
  // Sort by length desc so longer phrases match first
  const words=Object.keys(wordMap).sort((a,b)=>b.length-a.length);
  const re=new RegExp('('+words.map(w=>w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','gi');
  return text.replace(re,m=>{
    const key=m.toLowerCase();
    const color=wordMap[key]||'#D4A300';
    const label=labelMap&&labelMap[key];
    const tipAttr=label?` data-tip="${escHtml(label)}"`:'';
    // Same JP word HIGHLIGHT_DEVICE_KEYS recorded for this phrase — lets
    // hovering this EN highlight glow the source JP characters too.
    const deviceKey=deviceKeyMap&&deviceKeyMap[key];
    const deviceAttr=deviceKey?` data-device="${escHtml(deviceKey)}"`:'';
    return `<span class="dw-en" style="background:${color}"${tipAttr}${deviceAttr}>${escHtml(m)}</span>`;
  });
}
function escHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

// ── Modal ─────────────────────────────────────────────────────────────────
let currentN=null;

// Build character-level JP display with colored backgrounds
function renderJPChars(n, poem){
  const jp=(SRC_JP[String(n)]||'').replace(/\n/g,'');
  // Structure mode shows no device highlighting at all — only the
  // kami/shimo bracket (rendered separately in openModal) communicates ku.
  const devs=viewMode==='device' ? (SRC_DEVICES[String(n)]||{}) : {};
  const devLabels=viewMode==='device' ? (SRC_DEVICE_LABELS[String(n)]||{}) : {};
  const sorted=Object.keys(devs).sort((a,b)=>b.length-a.length);
  // Map each char index → device color, and → the matched word (so we can
  // look up its hover-tooltip label — e.g. "Kigo — Autumn" — below).
  const charColors=new Array(jp.length).fill(null);
  const charWords=new Array(jp.length).fill(null);
  let i=0;
  while(i<jp.length){
    let matched=false;
    for(const w of sorted){
      if(jp.startsWith(w,i)){
        const col=devs[w];
        for(let j=i;j<i+w.length;j++){ charColors[j]=col; charWords[j]=w; }
        i+=w.length;matched=true;break;
      }
    }
    if(!matched) i++;
  }

  // kami = verses 1-3, shimo = verses 4-5. Compute kami/shimo boundary
  // from verse lengths (newline-delimited) or a proportional fallback.
  const rawJP=SRC_JP[String(n)]||'';
  const verses=rawJP.includes('\n')?rawJP.split('\n'):null;
  let kamiEnd;
  if(verses&&verses.length===5){
    kamiEnd=verses[0].length+verses[1].length+verses[2].length;
  } else {
    kamiEnd=Math.round(jp.length*3/5);
  }

  // Single continuous vertical line — one char per row, no verse columns.
  // Kami/shimo is communicated ONLY by the bracket beside the text (see
  // .jp-sidebar) — characters stay plain white otherwise. A device word
  // gets an actual highlight background in its own color, strong enough
  // to read clearly at a glance. Consecutive characters of the SAME device
  // run are rounded only at the run's start/end, so a multi-character word
  // reads as one continuous highlighted block, not a stack of separate
  // rounded chips with visible seams between them.
  const spans=[];
  for(let p=0;p<jp.length;p++){
    const dev=charColors[p];
    let style='', tipAttr='', deviceAttr='', runCls='';
    if(dev){
      // Boundary is by MATCHED WORD, not just color — two distinct device
      // words that happen to share a color (e.g. two kakekotoba) must still
      // be treated as separate runs, each getting its own rounded ends.
      const isStart = p===0 || charWords[p-1]!==charWords[p];
      const isEnd = p===jp.length-1 || charWords[p+1]!==charWords[p];
      const rTop = isStart?'4px':'0', rBottom = isEnd?'4px':'0';
      // Full color, matching the legend swatch exactly (not a lightened
      // tint). Text stays black — the palette is kept light enough for that.
      style=` style="background:${dev};border-radius:${rTop} ${rTop} ${rBottom} ${rBottom};"`;
      const label=devLabels[charWords[p]];
      if(label) tipAttr=` data-tip="${escHtml(label)}"`;
      // data-device is the JP word itself — HIGHLIGHT_DEVICE_KEYS uses this
      // SAME word to tag the corresponding EN highlight in each translator's
      // text, so hovering either glows every tied highlight together.
      deviceAttr=` data-device="${escHtml(charWords[p])}"`;
      // run-start/run-end let the .glow hover effect (CSS) draw its white
      // ring only on the outer edges of the whole word, not around each
      // individual character — otherwise a 3-character word glows as three
      // separate stacked boxes instead of reading as one unit.
      runCls=(isStart?' run-start':'')+(isEnd?' run-end':'');
    }
    spans.push(`<span class="jp-ch${runCls}"${style}${tipAttr}${deviceAttr}>${escHtml(jp[p])}</span>`);
  }

  // Furigana — group consecutive characters covered by the same kanji-run
  // reading under one label, positioned beside that run (see .jp-furigana;
  // the column is a vertical FLEX stack of block characters, not real
  // writing-mode text, so a native <rt> would render sideways).
  const furiList = SRC_FURIGANA[String(n)] || [];
  const furiRuns=[]; let cursor=0;
  furiList.forEach(entry=>{
    const idx=jp.indexOf(entry.kanji, cursor);
    if(idx===-1) return;
    furiRuns.push({start:idx, end:idx+entry.kanji.length, reading:entry.reading});
    cursor=idx+entry.kanji.length;
  });
  const runIdxByChar=new Array(jp.length).fill(-1);
  furiRuns.forEach((r,ri)=>{ for(let j=r.start;j<r.end;j++) runIdxByChar[j]=ri; });

  let chars=''; let p=0;
  while(p<jp.length){
    const ri=runIdxByChar[p];
    if(ri===-1){ chars+=spans[p]; p++; continue; }
    let q=p;
    while(q<jp.length && runIdxByChar[q]===ri) q++;
    chars+=`<span class="jp-ruby-group">${spans.slice(p,q).join('')}<span class="jp-furigana">${escHtml(furiRuns[ri].reading)}</span></span>`;
    p=q;
  }
  return {html:chars, kamiEnd, total:jp.length};
}

// Traditional kanji numeral for 1-100 (十七, 二十, 百, ...) — used for the
// modal's poem-number caption so it reads as consistently Japanese as the
// rest of that vertical title, rather than mixing in arabic digits.
const KANJI_DIGITS=['','一','二','三','四','五','六','七','八','九'];
function toKanjiNumber(n){
  if(n===100) return '百';
  if(n<10) return KANJI_DIGITS[n];
  if(n<20) return '十'+(n%10 ? KANJI_DIGITS[n%10] : '');
  const tens=Math.floor(n/10), ones=n%10;
  return KANJI_DIGITS[tens]+'十'+(ones ? KANJI_DIGITS[ones] : '');
}

function openModal(n){
  currentN=n;
  const poem=POEMS[n-1];
  const csv=CSV[String(n)]||{};
  // Structure mode: no device data reaches the modal at all — no word
  // highlights, no device legend rows. Same underlying data either way,
  // just withheld from rendering.
  const hl=viewMode==='device' ? (HIGHLIGHTS[String(n)]||{}) : {};
  const devs=viewMode==='device' ? (SRC_DEVICES[String(n)]||{}) : {};

  // ── JP panel ──────────────────────────────────────────────────────────
  const jpP=document.getElementById('jpPanel');
  const {html:jpCharsHTML, kamiEnd, total}=renderJPChars(n, poem);

  // Sidebar segments: kami (green) then shimo (red), proportional
  const kamiFrac=kamiEnd/total;
  const sbKami=`<div class="jp-sidebar-seg" style="height:${(kamiFrac*100).toFixed(1)}%;background:${C.kami};" data-tip="Kami-no-ku"></div>`;
  const sbShimo=`<div class="jp-sidebar-seg" style="height:${((1-kamiFrac)*100).toFixed(1)}%;background:${C.shimo};" data-tip="Shimo-no-ku"></div>`;

  // Build poem-specific legend
  const legendColors=new Set(Object.values(devs));
  const legendRows=[];
  legendRows.push([C.kami,'Kami-no-ku']);
  legendRows.push([C.shimo,'Shimo-no-ku']);
  // Imagined ku — only if a translation bar actually has an imagined segment
  const hasImagined=poem.real&&poem.bars.some(b=>b.segs.some(s=>s.type==='imagined'));
  if(hasImagined) legendRows.push([C.imagined,'Imagined ku']);
  if(legendColors.has(C.kakekotoba)||Object.values(hl).some(h=>Object.values(h).includes(C.kakekotoba)))
    legendRows.push([C.kakekotoba,'掛詞 Kakekotoba']);
  if(legendColors.has(C.makurakotoba))
    legendRows.push([C.makurakotoba,'枕詞 Makurakotoba']);
  if(legendColors.has(C.kigo))
    legendRows.push([C.kigo,'季語 Kigo']);

  const legendRowsHTML=legendRows.map(([c,l])=>
    `<div class="lrow"><div class="lsw" style="background:${c}"></div>${escHtml(l)}</div>`
  ).join('');

  // Title (top-right) and legend (bottom-right) are siblings of the
  // scrollable jp-scroll wrapper, not inside it — so they stay anchored to
  // the page's corners like a book's running header/footer regardless of
  // how far the poem text itself scrolls.
  jpP.innerHTML=`
    <div class="jp-scroll">
      <div class="jp-inner">
        <div class="jp-sidebar">${sbKami}${sbShimo}</div>
        <div class="jp-chars-area"><div class="jp-chars">${jpCharsHTML}</div></div>
      </div>
    </div>
    <div class="title-jp">百人一首の${toKanjiNumber(n)}番</div>
    <div class="jp-legend"><div class="lgd-title">Legend</div>${legendRowsHTML}</div>
  `;

  // ── EN panel ──────────────────────────────────────────────────────────
  // Reference order: Dickens, Noguchi, Porter, MacCauley
  const MODAL_ORDER=['D','M','N','P'];
  // Per-line ku colors from the translation bar data
  const kuColor={kami:C.kami,shimo:C.shimo,imagined:C.imagined};
  const enP=document.getElementById('enPanel');
  const kuLabel={kami:'Kami-no-ku',shimo:'Shimo-no-ku',imagined:'Imagined line'};
  const blocks=MODAL_ORDER.map(lbl=>{
    const lines=csv[lbl]||[];
    const wordMap=hl[lbl]||{};
    const labelMap=viewMode==='device' ? ((HIGHLIGHT_LABELS[String(n)]||{})[lbl]||{}) : {};
    const deviceKeyMap=viewMode==='device' ? ((HIGHLIGHT_DEVICE_KEYS[String(n)]||{})[lbl]||{}) : {};
    // Match each line to its ku classification (from REAL_DATA bars)
    const bar=poem.real?poem.bars.find(b=>b.lbl===lbl):null;
    const segs=bar?bar.segs:null;
    const linesHTML=lines.map((ln,li)=>{
      const type=segs&&segs[li]?segs[li].type:null;
      const uc=type?kuColor[type]:'transparent';
      const lineTipAttr=type?` data-tip="${kuLabel[type]}"`:'';
      return `<div class="tl-row"><span class="tl" style="border-bottom-color:${uc}"${lineTipAttr}>${highlightLine(ln,wordMap,labelMap,deviceKeyMap)}</span></div>`;
    }).join('');
    return `<div class="trans-block">
      <div class="trans-label">${TRANS_NAMES[lbl]}</div>
      <div class="trans-lines">${linesHTML||'<span class="no-data">—</span>'}</div>
    </div>`;
  }).join('');

  enP.innerHTML=`<div class="trans-grid">${blocks}</div>`;
  // Title moved into the modal's own top bar (between the prev/next
  // arrows) rather than living inside the EN panel — it's poem-level
  // metadata, not part of either translation column, and putting it in
  // the header lets Prev/Next flank it directly instead of sitting far
  // below it on the English side only.
  document.getElementById('modalTitle').textContent = `Poem ${n} — ${csv.poet||''}`;

  document.getElementById('overlay').classList.add('open');
  document.getElementById('mPrev').disabled=n<=1;
  document.getElementById('mNext').disabled=n>=100;
}

function closeModal(){document.getElementById('overlay').classList.remove('open');currentN=null;}
function navModal(d){if(currentN)openModal(Math.max(1,Math.min(100,currentN+d)));}

document.getElementById('mClose').addEventListener('click',closeModal);
document.getElementById('mPrev').addEventListener('click',()=>navModal(-1));
document.getElementById('mNext').addEventListener('click',()=>navModal(1));
document.addEventListener('keydown',e=>{
  if(introOverlay.classList.contains('open')) return;
  if(e.key==='Escape')closeModal();
  if(e.key==='ArrowLeft')navModal(-1);
  if(e.key==='ArrowRight')navModal(1);
  // Reaching the full page is the top of the same zoom, not a separate
  // dead end — Down backs out of it exactly like zooming out from any
  // other stage, closing the modal and dropping the grid zoom one step,
  // so repeated Down presses eventually land back on the plain grid.
  if(e.key==='ArrowDown' && currentN && zoomedCell){
    closeModal();
    stepZoom(-1);
  }
});
document.getElementById('overlay').addEventListener('click',e=>{
  if(e.target===e.currentTarget)closeModal();
});

// ── View-mode toggle: Structure vs Devices ──────────────────────────────────
function setViewMode(mode){
  if(mode===viewMode) return;
  viewMode = mode;
  document.getElementById('vtStructure').classList.toggle('active', mode==='structure');
  document.getElementById('vtDevice').classList.toggle('active', mode==='device');
  document.querySelector('.legend').classList.toggle('structure-only', mode==='structure');
  const aleg=document.getElementById('authorLegend');
  if(aleg) aleg.classList.toggle('structure-only', mode==='structure');
  // Re-render every glyph in place (cheap: 100 small SVG strings). The
  // zoomed cell (if any) may be showing the text tier instead of bars —
  // applyCellZoomTier() re-derives the right content for it either way.
  document.querySelectorAll('#grid .pc').forEach(cell=>{
    if(cell===zoomedCell) return;
    const poem = POEMS[+cell.dataset.n - 1];
    cell.querySelector('.glyph-wrap').innerHTML = glyph(poem);
  });
  if(zoomedCell) applyCellZoomTier(zoomedCell);
  refreshAuthorGrids();
  if(currentN) openModal(currentN); // re-render the open modal too, if any
}
document.getElementById('vtStructure').addEventListener('click', ()=>setViewMode('structure'));
document.getElementById('vtDevice').addEventListener('click', ()=>setViewMode('device'));
document.getElementById('vtByPoem').addEventListener('click', ()=>setLayoutMode('poem'));
document.getElementById('vtByAuthor').addEventListener('click', ()=>setLayoutMode('author'));

function jumpToPoem(n){
  if(layoutMode!=='poem') setLayoutMode('poem');
  const cell=document.querySelector(`#grid .pc[data-n="${n}"]`);
  if(!cell) return;
  stepperLock=true;
  applyZoom(cell);
  openModal(n);
}
const poemJump=document.getElementById('poemJump');
poemJump.addEventListener('keydown',e=>{
  if(e.key==='Enter'){const n=+e.currentTarget.value;if(n>=1&&n<=100){jumpToPoem(n);e.currentTarget.blur();}}
});
poemJump.addEventListener('change',e=>{
  const n=+e.currentTarget.value;if(n>=1&&n<=100) jumpToPoem(n);
});

// ── Zoom: the whole grid scales, anchored on the selected poem ──────────
// Scale the complete grid around the selected poem.
const gw = document.getElementById('gw');
const grid = document.getElementById('grid');

// Hovering only selects a poem (swaps it to the self-contained card, so
// there's something to zoom into) — it does NOT scale the grid by itself.
// The grid only actually grows once the user explicitly zooms via the
// Up/Down arrow keys; otherwise moving the mouse across the grid would
// shift the whole layout on every cell, which read as the page jittering
// rather than a deliberate zoom action.
// Four presses: (1) the bars reappear, interactive — hover one to see the
// word at that position; (2) Japanese + English together, deliberately
// sized to fit the card completely with nothing cut off; (3) same content,
// now at a bigger/more legible scale; (4) reaching 100 opens the full poem
// page. Resting/hover (level 0) shows neither bars — just the poem number
// and poet — so there's something to reveal by zooming.
const ZOOM_STEP = 25;
// Skip level 2 (50) — jump directly between level 1 (25) and level 3 (75).
function stepZoom(dir){
  if(dir>0){
    if(zoomLevel<25) setZoomLevel(25);
    else if(zoomLevel<75) setZoomLevel(75);
    else setZoomLevel(100);
  } else {
    if(zoomLevel>75) setZoomLevel(75);
    else if(zoomLevel>25) setZoomLevel(25);
    else setZoomLevel(0);
  }
}
// The literal window IS the camera zoom — the grid's own transform:scale is
// set so exactly this many cells (the focal poem plus its buffer) fill
// .gw, magnifying every cell together (focal AND neighbors, in sync) like
// zooming into a map region — NOT a track re-partition, so the grid keeps
// its real 13×8 dimensions throughout (grid-template-columns/rows are
// never touched by JS).
function windowForLevel(val){
  if(val>=75) return {cols:3, rows:1};
  if(val>=50) return {cols:5, rows:3};
  if(val>0)   return {cols:7, rows:5};
  return {cols:GRID_COLS, rows:GRID_ROWS};
}
let zoomedCell = null;
// Only two states now — plain resting bars, or the book layout at
// whatever size the current zoom level calls for. No separate
// "interactive bars" stage: the very first zoom press already shows the
// full two-page book (source text + all four translations), just small.
let zoomTier = 'none'; // 'none' | 'book'
let zoomLevel = 0;
// Constant translate that recenters the focal poem in the viewport as the
// grid scales up around it — computed once per selection (see applyZoom),
// independent of the scale itself (transform-origin already keeps the
// focal point visually fixed as scale changes).
let zoomTx = 0, zoomTy = 0;
// Tracks the scale actually applied last, so zooming further IN can never
// visibly shrink the grid even if a rounding hiccup made the next tier's
// computed scale momentarily smaller.
let lastAppliedScale = 1;
// Measured at identity transform before zooming.
let nativeCellPx = 82;
// The grid's own resting footprint (measured the same way as
// nativeCellPx, at identity transform) — used instead of .gw's full box
// when fitting the zoom window. .gw also contains the row/column number
// rails (a sibling of #grid, not a child), so fitting against .gw's own
// size let the zoomed grid grow past the boundary those numbers mark;
// #grid's own rect already excludes that space, since the rail's own
// grid-row/column reserve it.
let restingGridW = 0, restingGridH = 0;

function clearZoom(){
  if(zoomedCell) restoreCellGlyph(zoomedCell);
  zoomedCell = null;
  grid.style.transform = '';
  grid.style.transformOrigin = '';
  zoomLevel = 0;
  zoomTier = 'none';
  grid.classList.remove('zoom-active');
}

function applyZoom(cell){
  if(cell === zoomedCell) return;
  if(zoomedCell) restoreCellGlyph(zoomedCell);
  // #grid has a CSS transition on transform — resetting it and measuring
  // on the very next line would catch it MID-ANIMATION back to identity,
  // not actually at identity, corrupting every measurement below. Killing
  // the transition just for this reset+measure step (then restoring it)
  // is what makes the reset actually take effect before we read anything.
  grid.style.transitionDuration = '0s';
  grid.style.transform = '';
  grid.getBoundingClientRect(); // force layout so the reset above is committed
  zoomedCell = cell;
  const col = +cell.dataset.col, row = +cell.dataset.row;
  selCol = col; selRow = row;
  updateRailActive();
  updateRailPoem(+cell.dataset.n);
  const cellRect = cell.getBoundingClientRect();
  nativeCellPx = cellRect.width;
  // Recenter the focal poem within the grid's resting footprint.
  const gridRect = grid.getBoundingClientRect();
  restingGridW = gridRect.width;
  restingGridH = gridRect.height;
  const fx = cellRect.left - gridRect.left + cellRect.width/2;
  const fy = cellRect.top - gridRect.top + cellRect.height/2;
  zoomTx = (restingGridW/2) - fx;
  zoomTy = (restingGridH/2) - fy;
  grid.style.transformOrigin = `${f(fx)}px ${f(fy)}px`;
  // .zoomed here gives hover its modest white-bg treatment (see
  // .pc.zoomed) so the "Poem N: Poet" label added in applyCellZoomTier is
  // actually legible at rest, not just once an arrow-key zoom press
  // happens — real bar data stays visible underneath it either way.
  cell.classList.add('zoomed');
  zoomTier = 'none';
  zoomLevel = 0;
  lastAppliedScale = 1;
  grid.classList.remove('zoom-active'); // fresh selection starts unzoomed — no spotlight yet
  applyCellZoomTier(cell);
  grid.style.transitionDuration = ''; // restore normal transition for zoom-level changes
  // No grid transform here — selecting/hovering a poem must not move the
  // grid at all. zoomTx/zoomTy/transformOrigin are only READY for when
  // setZoomLevel() (Up/Down) actually applies them.
}

function setZoomLevel(val){
  val = Math.max(0, Math.min(100, val));
  const prevLevel = zoomLevel;
  // Press 1 is too cramped a cell for four full translations to mean
  // anything at any font size — it shows source text + bars instead, same
  // as the resting glyph but interactive. Full translations only start at
  // press 2, once the grid's own scale has given the cell real room to lay
  // the whole book out and shrink it to fit — legibility isn't the goal
  // there, just that all the data is visibly present; press 3 is the same
  // book layout again, just bigger (the grid keeps growing).
  zoomTier = val>=50 ? 'book' : (val>0 ? 'bars' : 'none');
  zoomLevel = val;
  grid.classList.toggle('zoom-active', val>0);
  // .zoomed stays on continuously from hover onward (see applyZoom) —
  // toggling it off at val===0 would also drop the "Poem N: Poet" label
  // hovering is supposed to keep showing.
  if(val===0){
    grid.style.transform = '';
    lastAppliedScale = 1;
  } else {
    // The grid's scale is set so the literal WINDOW (7×5, then 5×3, then
    // 3×1 cells) fills the GRID's own resting footprint (restingGridW/H,
    // not .gw's full box) — this is the real camera pan/zoom, and it's
    // what makes every neighboring cell visibly grow/recede in sync with
    // the focal one, not just the focal card. grid-template-columns/rows
    // are never touched — same 13×8 dimensions throughout. Fitting against
    // .gw's full box (rather than the grid's own) let the zoomed content
    // grow past where the row/column number rails mark the boundary,
    // since those rails are .gw children too but not part of #grid.
    const win = windowForLevel(val);
    let scale = Math.min(
      (restingGridW*0.98) / (nativeCellPx*win.cols),
      (restingGridH*0.98) / (nativeCellPx*win.rows)
    );
    if(val > prevLevel) scale = Math.max(scale, lastAppliedScale);
    lastAppliedScale = scale;
    grid.style.transform = `translate(${f(zoomTx)}px, ${f(zoomTy)}px) scale(${scale})`;
  }
  if(zoomedCell) applyCellZoomTier(zoomedCell);
  if(val>=100 && prevLevel<100 && zoomedCell) openModal(+zoomedCell.dataset.n);
}

// The font-size math in renderZcBook is an estimate — real text doesn't
// wrap in perfectly even lines, so it can still run past its box for some
// translators. Rather than trust the estimate alone (which is what let
// English text get cut off at the bottom), measure the actual rendered
// overflow post-insert and shrink until it genuinely fits — "start small
// enough to fit everything comfortably" as a guarantee, not just a guess.
// Checking each .zc-book-lines/.gz-text element's OWN scrollHeight vs
// clientHeight never found real overflow — those elements have no height
// constraint of their own, so they just grow to fit their content and
// scrollHeight===clientHeight trivially. The thing that actually clips is
// their ancestor .zc-body (overflow:hidden) — that's the container whose
// overflow needs measuring, and everything inside it needs to shrink
// together until IT stops overflowing.
function shrinkToFitAll(wrap){
  const body = wrap.querySelector('.zc-body');
  if(!body) return;
  // Resize English text and labels first; retain Japanese text when possible.
  const texts = [...wrap.querySelectorAll('.zc-book-lines, .zc-book-lbl')];
  const header = wrap.querySelector('.zc-book-title');
  const jpText = wrap.querySelector('.gz-text');
  if(!texts.length) return;
  // Floors of 0.4px/0.6px (not 1px/1.5px) — starting sizes now already
  // scale down with the card itself (see renderZcBook), so this loop only
  // has to do fine-tuning most of the time, but a very small card (a
  // single native grid cell, ~40px) still needs real headroom below 1px
  // to fully converge rather than hitting the floor with overflow left.
  // jpText now has its own height:100%+overflow:hidden (see .gz-text in
  // style.css) instead of wrapping into a second vertical column when it
  // runs long — but that containment means its own overflow no longer
  // shows up in body.scrollHeight at all (it's clipped away before ever
  // reaching the ancestor), so relying on the body check alone would let
  // JP text silently clip its tail characters with nothing here ever
  // trying to shrink it back to fitting. jpOverflows is checked and acted
  // on independently for exactly that reason.
  // Checks scrollWidth too, not just scrollHeight — writing-mode:vertical-rl
  // text that's too tall for its one column doesn't grow the element's
  // HEIGHT at all (that's capped at 100%); it wraps into a second column,
  // which grows the element's WIDTH instead. A height-only check saw
  // scrollHeight===clientHeight (nothing ever "overflowed" vertically) and
  // considered it fully fit, while the wrapped-into second column sat
  // clipped and invisible — every character was still in the DOM
  // (textContent had them all), just silently painted nowhere.
  const jpOverflows = () => jpText && (
    jpText.scrollHeight > jpText.clientHeight + 0.5 ||
    jpText.scrollWidth > jpText.clientWidth + 0.5
  );
  let guard = 0;
  while((body.scrollHeight > body.clientHeight + 0.5 || jpOverflows()) && guard < 100){
    let shrunkAny = false;
    if(jpOverflows()){
      const cur = parseFloat(getComputedStyle(jpText).fontSize);
      // 1px, not lower — chasing a sub-pixel floor to fully eliminate the
      // last sliver of overflow for the longest poems (29 characters, the
      // corpus max) shrunk the text to the point of being genuinely
      // invisible, which is a worse outcome than a barely-clipped last
      // character at a size that's still actually visible once the grid's
      // own zoom scale (5-8x) blows it back up on screen.
      const next = Math.max(1, cur*0.94);
      if(next < cur){ jpText.style.fontSize = next.toFixed(2)+'px'; shrunkAny = true; }
    }
    if(body.scrollHeight > body.clientHeight + 0.5){
      texts.forEach(el=>{
        const cur = parseFloat(getComputedStyle(el).fontSize);
        const next = Math.max(0.4, cur*0.94);
        if(next < cur){ el.style.fontSize = next.toFixed(2)+'px'; shrunkAny = true; }
      });
      if(header){
        const cur = parseFloat(getComputedStyle(header).fontSize);
        const next = Math.max(0.6, cur*0.92);
        if(next < cur){ header.style.fontSize = next.toFixed(2)+'px'; shrunkAny = true; }
      }
    }
    if(!shrunkAny) break;
    guard++;
  }
}

function applyCellZoomTier(cell){
  const poem = POEMS[+cell.dataset.n - 1];
  const wrap = cell.querySelector('.glyph-wrap');
  // Fade the swap rather than an instant hard cut.
  wrap.style.opacity = '0';
  if(zoomTier==='none'){
    // At rest/hover: just the poem number and poet — no bars. Bars come
    // back the moment an actual zoom press happens.
    const poet = (CSV[String(poem.n)]||{}).poet || '';
    wrap.innerHTML = `<div class="zc-hover-lbl">Poem ${poem.n}: ${escHtml(poet)}</div>`;
  } else if(zoomTier==='bars'){
    // Press 1: source text + bars, interactive (withTips) — same visual
    // language as the resting grid, at the cell's own native size. Full
    // translations don't get room to mean anything at that size.
    wrap.innerHTML = glyph(poem, true);
  } else {
    // The card is given the cell's own NATIVE (unscaled) size, not the
    // scaled-up one — .zc-card lives inside #grid, which already carries
    // the zoom's transform:scale, so anything sized in here gets
    // multiplied by that scale automatically once painted. Sizing it to
    // cellPx*scale ourselves double-applied the scale (cellPx*scale²),
    // which is what made the card balloon far past its actual cell.
    // Native cellPx, left for the ancestor transform to blow up, lands it
    // at exactly one scaled cell's size — same as every neighbor.
    wrap.innerHTML = renderZoomCard(poem, nativeCellPx, nativeCellPx);
    shrinkToFitAll(wrap);
  }
  requestAnimationFrame(()=>{ wrap.style.opacity = '1'; });
}

function restoreCellGlyph(cell){
  cell.classList.remove('zoomed');
  const poem = POEMS[+cell.dataset.n - 1];
  cell.querySelector('.glyph-wrap').innerHTML = glyph(poem);
}

// Shared source-character markup (device-highlight spans + kami/shimo
// split) used by both the "text" tier and the "full" tier below — factored
// out so the two don't duplicate the char-matching loop.
function buildJpMarkup(n){
  const jpRaw = SRC_JP[String(n)] || '';
  const jp = jpRaw.replace(/\n/g,'');
  if(!jp) return null;
  const devs = viewMode==='device' ? (SRC_DEVICES[String(n)]||{}) : {};
  const devLabels = viewMode==='device' ? (SRC_DEVICE_LABELS[String(n)]||{}) : {};
  const sorted = Object.keys(devs).sort((a,b)=>b.length-a.length);
  const charColors = new Array(jp.length).fill(null);
  const charWords = new Array(jp.length).fill(null);
  let i=0;
  while(i<jp.length){
    let matched=false;
    for(const w of sorted){
      if(jp.startsWith(w,i)){
        const col=devs[w];
        for(let j=i;j<i+w.length;j++){ charColors[j]=col; charWords[j]=w; }
        i+=w.length; matched=true; break;
      }
    }
    if(!matched) i++;
  }
  const chars = jp.split('').map((ch,idx)=>{
    const dev = charColors[idx];
    if(!dev) return `<span class="gz-ch">${escHtml(ch)}</span>`;
    const isStart = idx===0 || charWords[idx-1]!==charWords[idx];
    const isEnd = idx===jp.length-1 || charWords[idx+1]!==charWords[idx];
    const rTop = isStart?'2px':'0', rBottom = isEnd?'2px':'0';
    const label = devLabels[charWords[idx]];
    const tipAttr = label ? ` data-tip="${escHtml(label)}"` : '';
    // data-device is the JP word itself — same pairing renderJPChars()
    // (the modal's own JP renderer) uses, so hovering the matching English
    // highlight glows these characters too, not just the modal's copy.
    const deviceAttr = ` data-device="${escHtml(charWords[idx])}"`;
    // run-start/run-end (same word-boundary logic as isStart/isEnd above)
    // let .gz-ch.glow's hover outline trace just the outer edge of the
    // whole word, not around each individual character — see .jp-ch.glow
    // in style.css for why a per-character box-shadow instead reads as a
    // stack of separate glowing chips.
    const runCls = (isStart?' run-start':'')+(isEnd?' run-end':'');
    return `<span class="gz-ch${runCls}" style="background:${dev};border-radius:${rTop} ${rTop} ${rBottom} ${rBottom};"${tipAttr}${deviceAttr}>${escHtml(ch)}</span>`;
  }).join('');
  const verses = jpRaw.includes('\n') ? jpRaw.split('\n') : null;
  const kamiEnd = (verses && verses.length===5)
    ? verses[0].length+verses[1].length+verses[2].length
    : Math.round(jp.length*3/5);
  return {chars, kamiFrac: kamiEnd/jp.length, len: jp.length};
}

// Two-page book layout — source text (with device highlights + kami/shimo
// bracket) on the left, poem title and all four full translations (ku-
// colored underlines, highlighted device words) on the right. Same data
// and rendering logic the full modal uses, just laid out at whatever size
// the current zoom level allows — every zoom press shows this same
// content, just bigger, never a separate lower-detail stage first.
function renderZcBook(poem, availW, availH){
  const n = poem.n;
  const csv = CSV[String(n)] || {};
  const poet = csv.poet || '';
  const markup = buildJpMarkup(n);
  if(!markup || !poem.real){
    return `<div class="zc-bars">${glyph(poem)}</div>`;
  }

  // Every gap/margin/border-width below (.zc-book's column gap, .zc-book-jp's
  // gap, .zc-book-en's gap, .zc-book-title's margin, each .zc-book-line's
  // border+padding+margin) is a fixed px value in CSS, tuned for a card
  // hundreds of px across — none of it shrinks when the text's own font-size
  // does. At a single native grid cell (~40px) that fixed overhead alone
  // (roughly 4px × ~20 lines/gaps once four full translations are laid out)
  // already exceeded the entire card, so shrinkToFitAll could shrink font
  // size to its floor and still never converge. uiScale brings all of it
  // down together, proportional to how small the card actually is.
  const uiScale = Math.max(0.06, Math.min(1, availH/300));
  // Scale the Japanese column with the available card height.
  const jpFontSize = Math.max(uiScale*1.4, Math.min(11, (availH*0.95) / (markup.len*0.95)));
  const sidebar = `<div class="gz-sidebar" style="width:${Math.max(1, 3*uiScale).toFixed(2)}px;">
    <div class="gz-sb-seg" style="height:${(markup.kamiFrac*100).toFixed(1)}%;background:${C.kami}"></div>
    <div class="gz-sb-seg" style="height:${((1-markup.kamiFrac)*100).toFixed(1)}%;background:${C.shimo}"></div>
  </div>`;
  const jpCol = `<div class="zc-book-jp" style="gap:${(4*uiScale).toFixed(2)}px;">${sidebar}<div class="gz-text" style="font-size:${jpFontSize.toFixed(2)}px;">${markup.chars}</div></div>`;
  const numCol = `<div class="zc-book-num">百人一首の${toKanjiNumber(n)}番</div>`;

  const hl = viewMode==='device' ? (HIGHLIGHTS[String(n)]||{}) : {};
  const kuColor = {kami:C.kami, shimo:C.shimo, imagined:C.imagined};
  const order = ['D','N','P','M'];
  // Starting sizes scale with the card's own height rather than a fixed
  // 6px/7px — those constants assumed a card hundreds of px tall; at a
  // native ~40px card they were already 6-7x bigger than the box itself,
  // leaving shrinkToFitAll's ~6%-per-iteration, 40-iteration loop (which
  // can only ever reach ~9% of its starting size) nowhere near enough
  // room to actually converge, so it gave up with most of the four
  // translations still overflowing out of the card entirely.
  const linesFontSize = Math.max(1, Math.min(7, availH*0.07));
  const lblFontSize = Math.max(1, Math.min(6, availH*0.06));
  const blocks = order.map(lbl=>{
    const lines = csv[lbl]||[];
    const wordMap = hl[lbl]||{};
    const labelMap = viewMode==='device' ? ((HIGHLIGHT_LABELS[String(n)]||{})[lbl]||{}) : {};
    const deviceKeyMap = viewMode==='device' ? ((HIGHLIGHT_DEVICE_KEYS[String(n)]||{})[lbl]||{}) : {};
    const bar = poem.bars.find(b=>b.lbl===lbl);
    const segs = bar ? bar.segs : null;
    const linesHTML = lines.map((ln,li)=>{
      const type = segs&&segs[li]?segs[li].type:null;
      const uc = type?kuColor[type]:'transparent';
      // Only the color is set here — border width/padding/margin are em
      // units in CSS (see .zc-book-line), so they automatically track
      // whatever size shrinkToFitAll ultimately shrinks this line's text
      // to, instead of a fixed px thickness that stayed constant while
      // the text around it kept shrinking.
      return `<div class="zc-book-line" style="border-bottom-color:${uc};">${highlightLine(ln,wordMap,labelMap,deviceKeyMap)}</div>`;
    }).join('');
    // Both start at the same computed size (rather than the label just
    // inheriting whatever the browser default happens to be) so the
    // translator name reads as a small caption next to the poem, not a
    // competing headline — and both are shrunk together in
    // shrinkToFitAll, so that ratio holds even as the body text shrinks
    // further to fit.
    return `<div class="zc-book-block"><div class="zc-book-lbl" style="font-size:${lblFontSize.toFixed(2)}px;">${escHtml(TRANS_NAMES[lbl])}</div><div class="zc-book-lines" style="font-size:${linesFontSize.toFixed(2)}px;">${linesHTML}</div></div>`;
  }).join('');

  const titleFontSize = Math.max(1.5, Math.min(9, availH*0.09));
  const enCol = `<div class="zc-book-en" style="gap:${(6*uiScale).toFixed(2)}px;">
    <div class="zc-book-title" style="font-size:${titleFontSize.toFixed(2)}px;margin-bottom:${(2*uiScale).toFixed(2)}px;">Poem ${n} — ${escHtml(poet)}</div>
    ${blocks}
  </div>`;

  return `<div class="zc-book" style="gap:${(10*uiScale).toFixed(2)}px;">${jpCol}${numCol}<div class="zc-book-divider"></div>${enCol}</div>`;
}

function renderZoomCard(poem, cardW, cardH){
  const body = renderZcBook(poem, cardW, cardH);
  // Explicit width/height (not inset percentages) — .zc-card sits inside
  // #grid, whose own transform:scale multiplies this size back up on
  // screen to match the zoomed cell exactly (see applyCellZoomTier).
  // .zc-body's padding is normally a fixed 8px in CSS, sized for a card
  // hundreds of px across — at a native ~40px card that alone ate over a
  // third of the box before any content was even laid out. Scaling it (and
  // .zc-book's inter-column gap) down proportionally to the card's own
  // size is what actually leaves room for shrinkToFitAll to work with,
  // instead of guaranteeing overflow no matter how small the text gets.
  const pad = Math.max(1, cardW*0.03).toFixed(1);
  const gap = Math.max(1, cardW*0.02).toFixed(1);
  return `<div class="zc-card" style="width:${cardW.toFixed(1)}px;height:${cardH.toFixed(1)}px;"><div class="zc-body" style="padding:${pad}px;gap:${gap}px;">${body}</div></div>`;
}

// ── Hover ──────────────────────────────────────────────────────────────────
// Deliberately minimal: hovering a poem changes exactly one thing — its
// number and poet's name appear. No neighbor distortion, no scale change,
// no shifting. Zooming (Up/Down) is a separate, explicit action.
function onGridMouseMove(e){
  const hovered = document.elementFromPoint(e.clientX, e.clientY)?.closest('#grid .pc');
  if(!hovered){ clearZoom(); return; }
  applyZoom(hovered);
}

function onCellClick(e, cell, poem){
  openModal(poem.n);
}

gw.addEventListener('mousemove', onGridMouseMove);
gw.addEventListener('mouseenter', ()=>{ stepperLock=false; });
gw.addEventListener('mouseleave', ()=>{ if(!stepperLock) clearZoom(); });
window.addEventListener('resize', clearZoom);

// Left/Right "snap" to the adjacent poem (wrapping past the legend's
// reserved block); Up/Down instead zoom in/out on whichever poem is
// currently hovered/selected. Disabled while the modal is open, where
// arrow keys already mean prev/next poem.
document.addEventListener('keydown', e=>{
  if(document.getElementById('overlay').classList.contains('open')) return;
  if(introOverlay.classList.contains('open')) return;
  if(!zoomedCell) return;
  if(e.key==='ArrowUp' || e.key==='ArrowDown'){
    e.preventDefault();
    stepZoom(e.key==='ArrowUp' ? 1 : -1);
    return;
  }
  const deltas = {ArrowRight:[0,1], ArrowLeft:[0,-1]};
  const d = deltas[e.key];
  if(!d) return;
  e.preventDefault();
  let row = +zoomedCell.dataset.row + d[0];
  let col = +zoomedCell.dataset.col + d[1];
  const next = document.querySelector(`#grid .pc[data-row="${row}"][data-col="${col}"]`);
  if(next) applyZoom(next);
});

// ── First-visit walkthrough ──────────────────────────────────────────────
// Shown automatically once per browser (gated on localStorage), reopenable
// anytime via the "?" button in the header. Mandatory in the sense that
// there's no click-outside-to-dismiss on the backdrop — a visitor has to
// either step through to the end or explicitly hit the ✕ — but the ✕ is
// always present so nobody's ever truly trapped.
const INTRO_SEEN_KEY = 'hyakuninIntroSeen';
const INTRO_STEPS = [
  {
    title: 'Comparative Translations of the Ogura Hyakunin Isshu',
    body: `<p>This project compares four historic English translations of Japan's
      classical <em>Ogura Hyakunin Isshu</em> — 100 poems compiled in the 13th
      century — against their original Japanese, poem by poem.</p>
      <p>This short walkthrough covers how to read the visualization. It takes
      about a minute.</p>`
  },
  {
    title: 'Each poem is five bars',
    body: `<div class="intro-bars-demo">
        <div class="lbl"><div class="intro-bar" style="height:70px;background:${C?.kami||'#2E9E6B'}"></div>O</div>
        <div class="lbl"><div class="intro-bar" style="height:52px;background:#bbb"></div>D</div>
        <div class="lbl"><div class="intro-bar" style="height:60px;background:#bbb"></div>N</div>
        <div class="lbl"><div class="intro-bar" style="height:45px;background:#bbb"></div>M</div>
        <div class="lbl"><div class="intro-bar" style="height:58px;background:#bbb"></div>P</div>
      </div>
      <p>The leftmost bar (<strong>O</strong>) is the original Japanese poem.
      The four beside it are the translators — Dickens (1866), Noguchi (1907),
      McCauley (1899), and Porter (1909) — sized by how many lines each one
      used.</p>
      <div class="intro-swatches">
        <div class="intro-swatch-row"><div class="intro-swatch" style="background:${C?.kami||'#2E9E6B'}"></div>Kami-no-ku — the poem's first half</div>
        <div class="intro-swatch-row"><div class="intro-swatch" style="background:${C?.shimo||'#E5503A'}"></div>Shimo-no-ku — the poem's second half</div>
        <div class="intro-swatch-row"><div class="intro-swatch" style="background:${C?.imagined||'#6F63C9'}"></div>Imagined line — content a translator added with no equivalent in the original</div>
      </div>`
  },
  {
    title: '"Structure" vs "Devices"',
    body: `<p>Every poem also has classical rhetorical devices baked into the
      Japanese — the <strong>Devices</strong> toggle highlights where they
      appear, and whether each translator preserved, or dropped, them.
      <strong>Structure</strong> hides these and shows only the bipartite
      kami/shimo skeleton above.</p>
      <div class="intro-swatches">
        <div class="intro-swatch-row"><div class="intro-swatch" style="background:${C?.kakekotoba||'#F28FC0'}"></div>掛詞 Kakekotoba — a pivot word carrying two meanings at once</div>
        <div class="intro-swatch-row"><div class="intro-swatch" style="background:${C?.makurakotoba||'#7EBBEE'}"></div>枕詞 Makurakotoba — a fixed ornamental "pillow word"</div>
        <div class="intro-swatch-row"><div class="intro-swatch" style="background:${C?.kigo||'#B4DE65'}"></div>季語 Kigo — a seasonal reference word</div>
      </div>`
  },
  {
    title: 'Browsing the poems',
    body: `<p><strong>By Poem</strong> shows all 100 poems in a grid — hover
      one to zoom in, click to open its full detail (original text, all four
      translations, and why each device was or wasn't preserved).</p>
      <p><strong>By Author</strong> instead shows one translator's entire
      100-poem output at a time, for spotting patterns across their whole
      body of work rather than poem-by-poem.</p>
      <p>Inside a poem's detail view: <strong>← Prev / Next →</strong> or the
      arrow keys move between poems, and <strong>Esc</strong> closes it.</p>`
  },
];

const introOverlay = document.getElementById('introOverlay');
const introStepsEl = document.getElementById('introSteps');
const introDotsEl = document.getElementById('introDots');
const introBackBtn = document.getElementById('introBack');
const introNextBtn = document.getElementById('introNext');
const introCloseBtn = document.getElementById('introClose');
const helpBtn = document.getElementById('helpBtn');
let introIdx = 0;

function renderIntro(){
  introStepsEl.innerHTML = INTRO_STEPS.map((s,i)=>
    `<div class="intro-step${i===introIdx?' active':''}"><h2>${s.title}</h2>${s.body}</div>`
  ).join('');
  introDotsEl.innerHTML = INTRO_STEPS.map((_,i)=>
    `<div class="intro-dot${i===introIdx?' active':''}"></div>`
  ).join('');
  introBackBtn.disabled = introIdx===0;
  introNextBtn.textContent = introIdx===INTRO_STEPS.length-1 ? 'Get Started' : 'Next →';
}
function showIntro(){
  introIdx = 0;
  renderIntro();
  introOverlay.classList.add('open');
}
function closeIntro(){
  introOverlay.classList.remove('open');
  try{ localStorage.setItem(INTRO_SEEN_KEY, '1'); }catch(e){}
}
introNextBtn.addEventListener('click', ()=>{
  if(introIdx < INTRO_STEPS.length-1){ introIdx++; renderIntro(); }
  else closeIntro();
});
introBackBtn.addEventListener('click', ()=>{
  if(introIdx > 0){ introIdx--; renderIntro(); }
});
introCloseBtn.addEventListener('click', closeIntro);
helpBtn.addEventListener('click', showIntro);
document.addEventListener('keydown', e=>{
  if(!introOverlay.classList.contains('open')) return;
  if(e.key==='Escape') closeIntro();
  if(e.key==='ArrowRight') introNextBtn.click();
  if(e.key==='ArrowLeft' && introIdx>0){ introIdx--; renderIntro(); }
});

let introAlreadySeen = false;
try{ introAlreadySeen = !!localStorage.getItem(INTRO_SEEN_KEY); }catch(e){}
if(!introAlreadySeen) showIntro();

// ── Custom hover tooltip + tied-highlight glow for [data-tip]/[data-device] ──
// Tooltip and cross-highlight behavior for linked source and translation words.
const hoverTip = document.getElementById('hoverTip');
let activeTipEl = null;
let glowingEls = [];

function clearGlow(){
  glowingEls.forEach(el=>el.classList.remove('glow'));
  glowingEls = [];
}

function positionTip(el){
  const rect = el.getBoundingClientRect();
  const gap = 10;
  hoverTip.style.left = (rect.right + gap) + 'px';
  hoverTip.style.top = (rect.top + rect.height/2) + 'px';
  // Flip to the LEFT of the element instead when there's no room on the
  // right (e.g. a highlight near the EN panel's right edge), so the
  // tooltip never gets clipped off-screen or forced to overlap the text
  // it's describing.
  requestAnimationFrame(()=>{
    const tipRect = hoverTip.getBoundingClientRect();
    if(tipRect.right > window.innerWidth - 8){
      hoverTip.style.left = (rect.left - gap) + 'px';
      hoverTip.classList.add('flip');
    } else {
      hoverTip.classList.remove('flip');
    }
  });
}

// Delegated on document (not just #overlay) so the grid's own [data-tip]
// elements — the zoom "text" tier's device-highlighted characters and
// kami/shimo sidebar — get the same instant tooltip as the modal.
document.addEventListener('mouseover', e=>{
  const el = e.target.closest('[data-tip]');
  if(!el || el===activeTipEl) return;
  activeTipEl = el;
  hoverTip.textContent = el.dataset.tip;
  hoverTip.classList.add('show');
  hoverTip.classList.remove('flip');
  positionTip(el);

  clearGlow();
  const key = el.dataset.device;
  if(key){
    // Not scoped to .jp-chars/.trans-lines (the modal's own containers) —
    // the zoom card's book layout uses different container classes but the
    // same data-device pairing, and a global attribute selector ties both
    // together without needing to enumerate every place this markup lives.
    glowingEls = [...document.querySelectorAll(`[data-device="${CSS.escape(key)}"]`)];
    glowingEls.forEach(g=>g.classList.add('glow'));
  }
});
document.addEventListener('mouseout', e=>{
  const leavingTip = e.target.closest('[data-tip]');
  const enteringTip = e.relatedTarget && e.relatedTarget.closest && e.relatedTarget.closest('[data-tip]');
  if(leavingTip && leavingTip!==enteringTip){
    activeTipEl = null;
    hoverTip.classList.remove('show');
    clearGlow();
  }
});

buildGrid();
}
